import os,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def shapes(grid):
    seen=set(); out=[]
    for i,row in enumerate(grid):
        for j,v in enumerate(row):
            if v and (i,j) not in seen:
                stack=[(i,j)]; comp=set()
                while stack:
                    a,b=stack.pop()
                    if (a,b) in seen or grid[a][b]!=v: continue
                    seen.add((a,b)); comp.add((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        r,c=a+da,b+db
                        if 0<=r<len(grid) and 0<=c<len(grid[0]): stack.append((r,c))
                rs=[a for a,b in comp]; cs=[b for a,b in comp]
                out.append({'color':v,'cells':comp,'top':min(rs),'left':min(cs),'h':max(rs)-min(rs)+1,'w':max(cs)-min(cs)+1})
    return out

def transform(grid):
    line=[i for i,row in enumerate(grid) if len(set(row))==1 and row[0]!=0][0]
    below=[s for s in shapes(grid) if s['top']>line][0]
    above=[s for s in shapes(grid) if s['top']<line]
    keep=max(above,key=lambda s:s['color'])
    canvas=[row[:] for row in grid[line+1:]]
    # erase nothing needed; paste kept shape directly above below shape, aligned columns
    top=below['top']-(line+1)-keep['h']-0  # relative in canvas: below_top_rel - keep_h
    below_top_rel=below['top']-(line+1)
    pat={ (a-keep['top'],b-keep['left']) for a,b in keep['cells'] }
    for da in range(keep['h']):
        for db in range(keep['w']):
            if (da,db) in pat:
                canvas[below_top_rel-keep['h']+da][below['left']+db]=keep['color']
    return canvas

